    // rgb(R G B / A) / rgba(R G B / A) notation
    if (match[9] !== undefined) {
      return (
        ((parse255(match[9]) << 24) | // r
          (parse255(match[10]) << 16) | // g
          (parse255(match[11]) << 8) | // b
          parse1(match[12])) >>> // a
