    for (const filterFunction of filter) {
      const [filterName, filterValue] = Object.entries(filterFunction)[0];
      if (filterName === 'dropShadow') {
        // $FlowFixMe[incompatible-type]
        const dropShadow = parseDropShadow(filterValue);
        if (dropShadow == null) {
          return [];
