  /**
   * Runs an easing function forwards.
   */
  in(easing: EasingFunction): EasingFunction {
    return easing;
  },

  /**
   * Runs an easing function backwards.
   */
  out(easing: EasingFunction): EasingFunction {
    return t => 1 - easing(1 - t);
  },

  /**
